#![cfg(windows)]

//! `say -vocal` 在计划阶段探测语音时长：语音比文本长时，文本段与语音事件
//! 都要覆盖整段语音，不能被文本时间截断。

mod common;

use std::fs;
use std::path::Path;

use webgal_video_export::api::{ExportOptions, build_plan};
use webgal_video_export::plan::AudioKind;

fn write(root: &Path, relative: &str, bytes: &[u8]) {
    let path = root.join(relative);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("create dir");
    }
    fs::write(path, bytes).expect("write fixture");
}

#[test]
fn long_voice_extends_the_say_segment() {
    let directory = tempfile::tempdir().expect("temp dir");
    let root = directory.path();
    write(root, "game/config.txt", b"Game_name:Voice;\n");
    write(root, "game/vocal/voice.wav", &common::silence_wav(2));
    write(
        root,
        "game/scene/start.txt",
        b"say:hi -vocal=voice.wav;\nsay:after;\nend;\n",
    );

    let plan = build_plan(&ExportOptions::new(root)).expect("build plan");
    let text = &plan.texts[0];

    // 默认演出参数: 文本 2 字 = 117×2 + 670 = 904ms, 语音 2000ms + tail 200ms 更长;
    // 再加自动播放等待 1570ms。
    assert_eq!(text.end_us - text.start_us, 3_770_000);

    let vocal = plan
        .audio
        .iter()
        .find(|event| event.kind == AudioKind::Vocal)
        .expect("语音事件");
    assert_eq!(vocal.end_us, Some(text.end_us));
    assert_eq!(plan.assets["vocal/voice.wav"].duration_us, Some(2_000_000));

    // 时间线也要等完整语音, 下一句从语音结束之后开始。
    assert_eq!(plan.texts[1].start_us, text.end_us);
}

#[test]
fn short_voice_keeps_the_text_timing() {
    let directory = tempfile::tempdir().expect("temp dir");
    let root = directory.path();
    write(root, "game/config.txt", b"Game_name:Voice;\n");
    write(root, "game/vocal/voice.wav", &common::silence_wav(1));
    write(
        root,
        "game/scene/start.txt",
        b"say:abcdefghijklmnopqrst -vocal=voice.wav;\nend;\n",
    );

    let plan = build_plan(&ExportOptions::new(root)).expect("build plan");
    let text = &plan.texts[0];

    // 文本 20 字 = 117×20 + 670 = 3010ms, 已经长于语音 1000 + 200ms。
    assert_eq!(text.end_us - text.start_us, 4_580_000);
}
